import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect } from 'storybook/test';
import { AuthProvider } from '../../context/AuthProvider';
import LoginPage from './index';

const meta = {
  component: LoginPage,
  tags: ['ai-generated', 'needs-work'],
  args: {
    ignoreAuthCheck: true,
  },
  decorators: [
    (Story) => (
      <AuthProvider
        evergreenAppURL="https://evergreen.example.com"
        localAuthRoute="/login"
        remoteAuthURL="https://auth.example.com"
        shouldUseLocalAuth
      >
        <Story />
      </AuthProvider>
    ),
  ],
} satisfies Meta<typeof LoginPage>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  play: async ({ canvas, userEvent }) => {
    const usernameInput = canvas.getByLabelText('Username');
    const passwordInput = canvas.getByLabelText('Password');
    await userEvent.type(usernameInput, 'admin', { delay: 50 });
    await userEvent.type(passwordInput, 'secret', { delay: 50 });
    await expect(usernameInput).toHaveValue('admin');
    await expect(passwordInput).toHaveValue('secret');
  },
};

